const replayExecutionEvents = `-- name: ReplayExecutionEvents :many
SELECT id, run_id, sequence, event_type, node_run_id, attempt_id, payload, occurred_at
FROM execution_events
WHERE run_id = $1
  AND sequence > $2
ORDER BY sequence
LIMIT $3
`

type ReplayExecutionEventsParams struct {
	RunID         uuid.UUID `json:"run_id"`
	AfterSequence int64     `json:"after_sequence"`
	PageSize      int32     `json:"page_size"`
}

func (q *Queries) ReplayExecutionEvents(ctx context.Context, arg ReplayExecutionEventsParams) ([]ExecutionEvent, error) {
	rows, err := q.db.Query(ctx, replayExecutionEvents, arg.RunID, arg.AfterSequence, arg.PageSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ExecutionEvent{}
	for rows.Next() {
		var i ExecutionEvent
		if err := rows.Scan(
			&i.ID,
			&i.RunID,
			&i.Sequence,
			&i.EventType,
			&i.NodeRunID,
			&i.AttemptID,
			&i.Payload,
			&i.OccurredAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

